import{_ as e,a,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"数据结构导论","description":"从抽象数据类型到树、图与查找，建立数据组织和算法成本之间的联系。","frontmatter":{"title":"数据结构导论","description":"从抽象数据类型到树、图与查找，建立数据组织和算法成本之间的联系。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 计算机与软件工程 · 数据结构、算法与软件设计","summary":"从抽象数据类型到树、图与查找，建立数据组织和算法成本之间的联系。","status":"active","related":[{"title":"算法导论（原书第3版）","link":"/life/personal/books/computing/introduction-to-algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"漫画算法","link":"/life/personal/books/computing/comic-algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"程序员的数学","link":"/life/personal/books/computing/programmers-math","kind":"书籍导读","scope":"general","audience":"general"},{"title":"重构 改善既有代码的设计（第2版）","link":"/life/personal/books/computing/refactoring","kind":"书籍导读","scope":"general","audience":"general"}],"prev":false,"next":{"text":"算法导论（原书第3版）","link":"/life/personal/books/computing/introduction-to-algorithms"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"算法导论（原书第3版）","link":"/life/personal/books/computing/introduction-to-algorithms"}},"headers":[],"relativePath":"life/personal/books/computing/data-structures.md","filePath":"life/personal/books/computing/data-structures.md"}'),i={name:"life/personal/books/computing/data-structures.md"};function l(n,t,d,s,c,p){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="数据结构导论" tabindex="-1">数据结构导论 <a class="header-anchor" href="#数据结构导论" aria-label="Permalink to &quot;数据结构导论&quot;">​</a></h1><p><a href="./../overview">返回分类书单</a></p><p><strong>分类：计算机与软件工程 / 数据结构、算法与软件设计</strong></p><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>这本书在书单中承担计算机核心基础的角色，适合已经掌握一种编程语言、希望理解数据怎样组织和处理的读者。阅读重点是将抽象操作、实际存储方式和时间空间成本联系起来，而不只是记住结构的名称。</p><p>可以围绕一份不断变化的数据提出问题：需要按位置访问还是按键查找，需要有序还是只需去重，插入和查询各占多少比例。结构的选择应当由这些操作需求决定。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p><strong>版本待确认。</strong> 书单没有提供作者、版次或 ISBN，无法唯一识别同名教材。以下为本站主题导读，不是原书目录；不推定它采用 C、Java 或其他语言。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p>《数据结构导论》作者与版本待确认。这个名称也常出现在其他教材的章节名和课程名中，检索命中不能直接作为本书身份。需按版权页作者、出版社、ISBN 以及采用语言定位，再核实作者教学或研究背景；当前不编写无法归属的学术头衔。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合熟悉变量、函数和一种编程语言的读者，以及希望改善集合选型的开发者。若课程采用 C，应先掌握指针；若目标是业务实践，可以先围绕查询、更新和内存预算来读。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>导读主题</th><th>阅读与练习目标</th></tr></thead><tbody><tr><td>抽象数据类型与复杂度</td><td>将操作契约和实现方式分开，认识时间复杂度、空间复杂度与输入规模。</td></tr><tr><td>线性表</td><td>比较顺序存储和链式存储，解释随机访问、插入和删除的不同成本。</td></tr><tr><td>栈与队列</td><td>用受限的访问顺序表达任务，练习括号匹配、层次遍历或任务缓冲。</td></tr><tr><td>串与数组</td><td>理解字符序列、下标映射和连续存储，关注边界与表示方式。</td></tr><tr><td>树与二叉树</td><td>掌握递归结构、遍历和层次关系，区分二叉树与二叉搜索树。</td></tr><tr><td>图</td><td>比较邻接矩阵与邻接表，使用遍历描述连通、依赖和可达性。</td></tr><tr><td>查找</td><td>比较顺序查找、二分查找、搜索树和哈希，识别各自的前提条件。</td></tr><tr><td>排序</td><td>从稳定性、额外空间和输入特征评价算法，避免只记平均复杂度。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p>以下为本站阅读评析，用可实践的阅读目标表达收获，不代表书单提供者已经读完、任职或完成相应项目。版本未明时，评析只针对本页明确标注的主题或参考版本。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><blockquote><p>结构的好坏，必须放进操作比例里判断。</p></blockquote><p>这是本站原创阅读提炼，不是原书引文；没有可核对页码的原文不作逐字摘抄。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p>给同一组任务分别设计顺序表和链表，写清按位置访问、头部插入、查找后删除的成本。这个练习能纠正“链表插入总是快”之类省略定位成本的说法，并训练从需求推导表示方法。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>在版本未确认时，不评价本册习题数量和实现质量。基础教材容易被读成定义合集，建议每个结构只做一个小实现，但必须覆盖空集合、单元素和重复键，并写清维持的结构性质。</p><p><strong>推荐语（本站原创，非原书引用）：</strong> 推荐给已经会写程序、却还说不清集合选择理由的人：把结构与成本连起来，代码选择才有解释。</p><h2 id="来源与核对入口" tabindex="-1">来源与核对入口 <a class="header-anchor" href="#来源与核对入口" aria-label="Permalink to &quot;来源与核对入口&quot;">​</a></h2><ul><li>书名来自本次书单；原书作者与逐章目录待版权页核对。</li><li><a href="https://opendatastructures.org/" target="_blank" rel="noopener noreferrer">Open Data Structures</a>：公开的数据结构教材，可辅助比较实现与复杂度，不是本书目录来源。</li><li><a href="https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-fall-2011/" target="_blank" rel="noopener noreferrer">MIT 6.006 算法导论课程</a>：补充练习与讲义入口。</li></ul>',26)])])}const g=e(i,[["render",l]]);export{u as __pageData,g as default};
